sys_ux_client_script.script:
/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
    var buttonId = "markbtn_3";
    var buttonData = api.data.markascomplete_1.output.buttonData;
    const button = buttonData.find(btn => btn.buttonId === buttonId);

    // Return the buttonState if found, otherwise return null or a default value
    var buttonState =  button ? button.buttonState : false;


	return buttonState ? "Mark as Incomplete" : "Mark as Complete";
}
